"use strict";
const {spawnSync}=require("node:child_process");
const repo="BestNameYet/Terminals",id=6652181439,apiPath="repos/"+repo+"/issues/comments/"+id;
function call(args){
 const p=spawnSync("gh",["api",...args],{encoding:"utf8",maxBuffer:10*1024*1024,timeout:30000,env:process.env});
 if(p.error||p.status!==0)throw Error(p.error?.message||p.stderr);
 return JSON.parse(p.stdout);
}
const orig=call([apiPath]);
if(!orig.issue_url.endsWith("/issues/4"))throw Error("wrong scratchpad issue");
const doc=JSON.parse(orig.body);
if(doc.header.task_id!=="audit-current-program-surfaces-20261104")throw Error("unexpected scratchpad task");
if(doc.header.revision!==1||doc.entries.length!==1)throw Error("scratchpad changed; manual reconcile");
const now=new Date().toISOString(), index=doc.entries.length, rev=doc.header.revision+1;
doc.entries.push({
 caption:{entry_id:"audit-current-program-surfaces-20261104."+rev,index,event:"verification",subject_id:"verified-program-mode-and-remaining-gaps",timestamp_utc:now,revision:rev,status:"in_progress"},
 work:"VERIFIED CURRENT STATE: The Issue #3 workflow now accepts $/gh/@; @ dispatches to a Node.js program-mode dispatcher using the registry in workspaces/programs/applications.json. The single registered app is scratchpad. Direct Issue #3 commands '@ programs' and '@ run scratchpad' succeeded and persisted structured JSON menus to workspaces/terminalruns/ (run IDs 41986461596 and 41986464708; results GPT6_0000000239-catalog_e2e_audit-Terminals_20261105T071958014Z.json and GPT6_0000000241-scratchpad_menu_e2e-Terminals_20261105T072001319Z.json). The scratchpad application implementation and pure core exist. Node syntax checks passed, and 11/11 core unit tests passed (terminal run 41986472188). Scratchpad code includes start, edit, new, new_entry, edit_entry, submit_json, status, complete, terminate, recover; live program start and mutations have NOT been verified. Critical architectural mismatch: scratchpad.js creates/edits its program control/render comment in Issue #5; requirement is at least TWO comments in Issue #3 per program instance, one command input and one rendered terminal. Neither the workflow nor app currently realizes that pair; current terminal stdout remains in terminalruns files. Issue #4 and #5 must be effects-only storage for scratchpad application. Reusable control-comment leasing code and state file exist, but no live full lifecycle test. AGENTS.md and terminals_requirements.json remain v1.0.0, do not include new scratchpad rules; workspaces/scratchpads/comment.schema.json is absent; root README.md absent. The earlier scratchpad policy command run 41982933935 failed during parsing and published no modifications. No repository source changes made by this status audit. NEXT: design/implement pair allocation and rendering in Issue #3; align app to use that surface and keep Issue #4/#5 as effects; then verify lifecycle/new/edit/end-to-end, update SRS and machine projection, AGENTS and requirements." 
});
doc.header.revision=rev;doc.header.updated_at=now;
call(["--method","PATCH",apiPath,"-f","body="+JSON.stringify(doc,null,2)]);
const after=call([apiPath]);
const check=JSON.parse(after.body);
if(JSON.stringify(check)!==JSON.stringify(doc))throw Error("scratchpad read-back mismatch");
console.log(JSON.stringify({status:"VERIFIED",issue:4,comment_id:id,revision:rev,entries:doc.entries.length,url:after.html_url}));
